    21	function validateCardNumber(value: string): boolean {
    22	    let sum = 0;
    23	    let shouldDouble = false;
    24	
    25	    // Loop through the card number from right to left
    26	    for (let i = value.length - 1; i >= 0; i--) {
    27	        let intVal = parseInt(value[i], 10);
    28	
    29	        // Double every second digit from the right
    30	        if (shouldDouble) {
    31	            intVal *= 2;
    32	            if (intVal > 9) {
    33	                intVal -= 9;
    34	            }
    35	        }
    36	
    37	        sum += intVal;
    38	        shouldDouble = !shouldDouble;
    39	    }
    40	
    41	    return sum % 10 === 0;
    42	}
